pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address logger, bool status) public {
        // Restrict: only the owner can call setApprovedLogger
        vm.assume(owner != address(0)); // avoid zero address issues
        // Give the owner some ether for potential transfers if needed
        vm.deal(owner, 1 ether);

        // Try to call setApprovedLogger as the owner; if it reverts, the bug is triggered
        vm.prank(owner);
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.setApprovedLogger.selector, logger, status)
        );

        // If the call succeeded, then for the reference C, the mapping must be updated
        if (success) {
            // Check that after a successful setApprovedLogger(owner, logger, true),
            // the approvedToLog(logger) == true for any logger (including owner)
            vm.prank(owner);
            bool approved = c.approvedToLog(logger);
            assertTrue(approved == status);
        } else {
            // If it reverts (buggy version), then the mapping cannot have changed:
            // The only way to change it is via setApprovedLogger, which now always reverts.
            // So approvedToLog should remain false for all addresses initially.
            bool approved = c.approvedToLog(logger);
            assertTrue(approved == false);
        }
    }
}

