pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        // Ensure addr is not the zero address (to avoid edge cases with owner)
        vm.assume(addr != address(0));

        // The owner can set the approvedLogger
        // We'll use the contract itself as owner (since no constructor sets owner, it's address(0) by default)
        // Actually setApprovedLogger requires onlyOwner which checks msg.sender == _contractOwner.
        // Since _contractOwner is private, we cannot read it. But we can try to call setApprovedLogger as the owner.
        // If we don't know the owner, we can try to prank as the contract deployer (address(this) in setUp)
        // In Foundry, default msg.sender is address(this) which deployed the contract via new C()

        // First, check initial status
        bool initialStatus = c.approvedToLog(addr);

        // Attempt to set approval via setApprovedLogger (reverts in buggy version)
        (bool success, ) = address(c).call(abi.encodeWithSignature("setApprovedLogger(address,bool)", addr, true));

        // After the call, read the status again
        bool newStatus = c.approvedToLog(addr);

        // The rule: if the call succeeded, then newStatus should be true; if it reverted, newStatus should equal initialStatus
        if (success) {
            assertTrue(newStatus == true, "After successful setApprovedLogger, status should be true");
        } else {
            assertTrue(newStatus == initialStatus, "After revert, status should not change");
        }
    }
}

